// Build the shared envelope from whichever trigger fired, and identify the client by the
// SENDER's email (matched against the Notion registry in the next node). Chat-trigger runs
// have no sender, so they fall back to demo_client for local testing.
const t = $input.first().json;
const subject = t.subject || t.Subject || 'RFQ';
const text = t.text || t.snippet || t.chatInput || t.body || '';
function headerVal(obj, name){ try { const hs=(obj.payload&&obj.payload.headers)||obj.headers; if(Array.isArray(hs)){ const h=hs.find(x=>String(x.name).toLowerCase()===name); return h?h.value:null; } if(hs&&typeof hs==='object'){ return hs[name] ?? hs[name.charAt(0).toUpperCase()+name.slice(1)] ?? null; } } catch(e){} return null; }
let fromRaw = t.from || t.From || headerVal(t,'from') || '';
if (fromRaw && typeof fromRaw==='object') { fromRaw = (fromRaw.value&&fromRaw.value[0]&&(fromRaw.value[0].address||fromRaw.value[0].value)) || fromRaw.address || fromRaw.text || ''; }
const m = String(fromRaw).match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
const sender_email = m ? m[0].toLowerCase() : null;
const fallback_client_id = sender_email ? null : 'demo_client';

// Thread context — lets the reply land INSIDE the reseller's original RFQ thread instead of
// opening a new conversation. Gmail threads a reply on threadId + a matching subject, so the
// subject must be the original one prefixed with 'Re: ', never a synthetic one.
// Chat-trigger runs have no thread; every field is null and threading degrades to a new mail.
const thread_id = t.threadId || t.thread_id || null;
const message_id = headerVal(t, 'message-id') || null;
// Only meaningful when there IS a thread to reply into — otherwise a chat run with no subject
// would ship a bare 'Re: RFQ' instead of letting the caller build a real one.
const reply_subject = thread_id ? (/^re:\s/i.test(subject) ? subject : `Re: ${subject}`) : null;
const email_context = { thread_id, message_id, reply_subject };
return [{ json: { sender_email, fallback_client_id, email_context, data: { subject, text } } }];

// Resolve the client ONCE from the registry by the SENDER's email (or the chat fallback id),
// enforcing Client Status. The n8n Notion node flattens properties as 'property_<snake_case>'.
// Outputs resolved:true (proceed) or resolved:false (rejected) — 'Client OK?' branches on it.
//   - unknown_sender: no registry row matches the sender email.
//   - inactive: the matched client is 'paused' or 'churned'.
const env = $('Build Envelope').first().json;
const senderEmail = (env.sender_email || '').toLowerCase();
const fallbackId = env.fallback_client_id;
const rows = $input.all();
function prop(props, name){ const p = props && props[name]; if(!p && p!==false) return null; if(typeof p==='string') return p; return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; const email=String(prop(props,'property_commercial_contact_email')||'').toLowerCase(); const cid=prop(props,'property_client_id'); if(senderEmail && email && email===senderEmail){ match=props; break; } if(!senderEmail && fallbackId && cid===fallbackId){ match=props; break; } }
if(!match){ return [{ json: { resolved:false, reason:'unknown_sender', sender_email: senderEmail||null, data: env.data } }]; }
const clientStatus = prop(match,'property_client_status');
const wantId = prop(match,'property_client_id');
if(clientStatus==='paused' || clientStatus==='churned'){ return [{ json: { resolved:false, reason:'inactive', client_id: wantId, client_status: clientStatus, sender_email: senderEmail||null, data: env.data } }]; }

// Outbound identity. 'trial' clients send from the demo address so pilot traffic stays
// visibly separate from production. Both must be VERIFIED 'Send mail as' aliases on the
// Gmail account that owns the credential, or Gmail rejects drafts.send.
// Keep in sync with 04-proposal-assembly.json -> 'Map Client Config' (standalone fallback).
const DEMO_FROM_ALIAS = 'demo@cifral.io';
const PROD_FROM_ALIAS = 'proposal@cifral.io';
function resolveFromAlias(status){ return status === 'trial' ? DEMO_FROM_ALIAS : PROD_FROM_ALIAS; }
// send_mode is the per-client kill switch: 'send' delivers the reply, 'draft' only parks it
// in the mailbox (the pre-production behaviour). Anything other than 'draft' means 'send'.
function resolveSendMode(raw){ return String(raw || 'send').trim().toLowerCase() === 'draft' ? 'draft' : 'send'; }

const client_config = {
  client_id: wantId,
  client_name: prop(match,'property_client_name'),
  status: clientStatus,
  service_tier: prop(match,'property_service_tier'),
  commercial_contact_email: prop(match,'property_commercial_contact_email'),
  reply_to: senderEmail || prop(match,'property_commercial_contact_email'),
  templates: { en: prop(match,'property_template_id_en'), es: prop(match,'property_template_id_es') },
  proposals_folder_id: prop(match,'property_proposals_folder_id'),
  reference_docs_folder_id: prop(match,'property_reference_docs_folder_id'),
  pricing_sheet_id: prop(match,'property_pricing_sheet_id'),
  proposal_config_sheet_id: prop(match,'property_proposal_config_sheet_id'),
  notification_chat_id: prop(match,'property_notification_chat_id'),
  from_alias: resolveFromAlias(clientStatus),
  send_mode: resolveSendMode(prop(match,'property_send_mode'))
};
return [{ json: { resolved:true, client_id: wantId, client_config, sender_email: senderEmail||null, email_context: env.email_context || null, data: env.data, status: 'ok', errors: [] } }];

