// proposal_only: assemble the document from RFQ + generated content, with NO pricing block.
// email_context is per-request (which thread to reply in) so it travels beside client_config,
// not inside it; Module 4 treats it as optional and falls back to a fresh mail without it.
const m1 = $('Call Module 1').first().json;
const m2 = $('Call Module 2').first().json;
return [{ json: {
  client_id: m1.client_id,
  proposal_config: $('Build Proposal Config').first().json.proposal_config,
  client_config: m1.client_config || null,
  email_context: $('Build Envelope').first().json.email_context || null,
  status: 'ok',
  errors: [],
  data: { rfq: m1.data, content: m2.data, pricing: null }
} }];

